var p = Math.max(1, Number(page || 1));
var base = String(basicUrl || "https://skrbtso.top").replace(/\/+$/, "");
var keyword = String(s || "").trim();
if (!keyword) return [];

function clean(v) {
    return String(v || "")
        .replace(/<script[\s\S]*?<\/script>/gi, "")
        .replace(/<style[\s\S]*?<\/style>/gi, "")
        .replace(/<[^>]+>/g, " " )
        .replace(/&nbsp;/gi, " " )
        .replace(/&amp;/gi, "&")
        .replace(/&lt;/gi, "<")
        .replace(/&gt;/gi, ">")
        .replace(/&#39;/gi, "'")
        .replace(/&quot;/gi, "\"")
        .replace(/\s+/g, " " )
        .trim();
}
function sizeBytes(text) {
    var m = String(text || "").replace(/,/g, "").match(/([0-9.]+)\s*(B|KB|MB|GB|TB)/i);
    if (!m) return 0;
    var n = Number(m[1] || 0);
    var u = String(m[2] || "B").toUpperCase();
    var pow = {B:0,KB:1,MB:2,GB:3,TB:4}[u] || 0;
    return Math.round(n * Math.pow(1024, pow));
}
function absUrl(href) {
    href = String(href || "").replace(/&amp;/g, "&");
    if (/^https?:\/\//i.test(href)) return href;
    if (href.indexOf("//") === 0) return "https:" + href;
    if (href.charAt(0) === "/") return base + href;
    return base + "/" + href.replace(/^\.\//, "");
}
function request(url) {
    return fetch(url, {
        headers: {
            "User-Agent": "Mozilla/5.0 (Linux; Android 16) AppleWebKit/537.36 Chrome/128.0 Mobile Safari/537.36",
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.6",
            "Referer": base + "/"
        },
        timeout: 12000
    });
}

var firstUrl = base + "/search?keyword=" + encodeURIComponent(keyword);
var html = "";
var url = firstUrl;
if (p > 1) {
    var first = request(firstUrl);
    var ar = /<a[^>]+href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
    var am;
    while ((am = ar.exec(first)) !== null) {
        if (clean(am[2]) === String(p)) {
            url = absUrl(am[1]);
            break;
        }
    }
    if (url === firstUrl) url = firstUrl + "&page=" + p;
    html = url === firstUrl ? first : request(url);
} else {
    html = request(url);
}

html = String(html || "");
if (!html) throw new Error("SkrBT 返回空页面");
if (/cf-chl-|cloudflare|captcha|access denied|forbidden/i.test(html) && html.indexOf("list-unstyled") < 0) {
    throw new Error("SkrBT 被 Cloudflare/风控拦截");
}

var out = [];
var re = /<ul[^>]*class=["'][^"']*list-unstyled[^"']*["'][^>]*>([\s\S]*?)<\/ul>/gi;
var m;
while ((m = re.exec(html)) !== null) {
    var block = m[1] || "";
    var detail = block.match(/href=["']([^"']*\/detail\/[^"']*)["']/i);
    if (!detail) continue;
    var detailUrl = absUrl(detail[1]);
    var hm = detailUrl.match(/([0-9a-fA-F]{40})/);
    if (!hm) {
        hm = block.match(/([0-9a-fA-F]{40})/);
        if (!hm) continue;
    }
    var hash = String(hm[1]).toUpperCase();

    var tm = block.match(/<a[^>]*class=["'][^"']*rrt[^"']*["'][^>]*>([\s\S]*?)<\/a>/i);
    if (!tm) tm = block.match(/<li[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/i);
    var title = clean(tm ? tm[1] : "");
    if (!title) title = hash;

    var meta = "";
    var mm = block.match(/<li[^>]*class=["'][^"']*rrmi[^"']*["'][^>]*>([\s\S]*?)<\/li>/i);
    if (mm) meta = clean(mm[1]);
    var sm = meta.match(/([0-9.]+)\s*(B|KB|MB|GB|TB)/i);
    var dm = meta.match(/(20\d{2}[-/.]\d{1,2}[-/.]\d{1,2}(?:\s+\d{1,2}:\d{2}(?::\d{2})?)?)/);
    var files = (block.match(/<li[^>]*class=["'][^"']*rrf[^"']*["']/gi) || []).length;

    var magnet = "magnet:?xt=urn:btih:" + hash + "&dn=" + encodeURIComponent(title);
    var desc = [];
    if (files > 0) desc.push("文件 " + files);
    if (meta) desc.push(meta);

    out.push({
        title: title,
        magnet: magnet,
        rawUrl: detailUrl,
        hash: hash,
        bytes: sizeBytes(sm ? sm[0] : meta),
        seeders: -1,
        peers: -1,
        date: dm ? dm[1].replace(/[/.]/g, "-") : "",
        desc: desc.join(" · " )
    });
}
if (!out.length && /没有|无结果|not found|no results/i.test(clean(html))) return [];
if (!out.length) throw new Error("SkrBT 页面结构变化或当前请求未获得搜索结果");
return out;
